-- Cash-in workflows bypass Manager approval; cash-out workflows retain it.
-- Internal receipt, voucher, and dividend references are generated by the database.

BEGIN;

DO $$
DECLARE
  v_definition TEXT;
  v_original_definition TEXT;
  v_old TEXT;
  v_new TEXT;
BEGIN
  v_definition := pg_get_functiondef(
    'public.submit_transaction_workflow(uuid,text,text,text,uuid,uuid,text,numeric,text,text,jsonb)'::REGPROCEDURE
  );

  v_original_definition := v_definition;
  v_old := 'counterparty_name,[[:space:]]*amount,[[:space:]]*payment_method,[[:space:]]*description,'
    || '[[:space:]]*payload,[[:space:]]*status,[[:space:]]*cash_release_required,'
    || '[[:space:]]*cash_release_status,[[:space:]]*created_by,[[:space:]]*created_by_auth_id,';
  v_new := 'counterparty_name, amount, payment_method, description, payload, approved_payload, status,' || chr(10)
    || '    cash_release_required, cash_release_status, created_by, created_by_auth_id,';
  v_definition := regexp_replace(v_definition, v_old, v_new);
  IF v_definition = v_original_definition THEN
    RAISE EXCEPTION 'Unable to patch transaction workflow insert columns';
  END IF;

  v_original_definition := v_definition;
  v_old := 'trim\(p_description\),[[:space:]]*p_payload,[[:space:]]*''pending_approval'','
    || '[[:space:]]*v_cash_out,[[:space:]]*''not_required'',[[:space:]]*v_staff_id,'
    || '[[:space:]]*v_auth_id,[[:space:]]*p_submission_key,[[:space:]]*v_hash';
  v_new := 'trim(p_description), p_payload,' || chr(10)
    || '    CASE WHEN v_direction = ''cash_in'' THEN p_payload ELSE NULL END,' || chr(10)
    || '    CASE WHEN v_direction = ''cash_in'' THEN ''approved'' ELSE ''pending_approval'' END,' || chr(10)
    || '    v_cash_out, ''not_required'', v_staff_id, v_auth_id, p_submission_key, v_hash';
  v_definition := regexp_replace(v_definition, v_old, v_new);
  IF v_definition = v_original_definition THEN
    RAISE EXCEPTION 'Unable to patch transaction workflow initial status';
  END IF;

  v_original_definition := v_definition;
  v_old := 'v_workflow_id,[[:space:]]*''submitted'',[[:space:]]*''pending_approval'','
    || '[[:space:]]*v_auth_id,[[:space:]]*v_staff_id,';
  v_new := 'v_workflow_id, ''submitted'',' || chr(10)
    || '    CASE WHEN v_direction = ''cash_in'' THEN ''approved'' ELSE ''pending_approval'' END,' || chr(10)
    || '    v_auth_id, v_staff_id,';
  v_definition := regexp_replace(v_definition, v_old, v_new);
  IF v_definition = v_original_definition THEN
    RAISE EXCEPTION 'Unable to patch transaction workflow submission event';
  END IF;

  EXECUTE v_definition;
END;
$$;

DO $$
DECLARE
  v_definition TEXT;
  v_original_definition TEXT;
  v_old TEXT;
  v_new TEXT;
BEGIN
  v_definition := pg_get_functiondef(
    'public.record_member_financial_entry_before_auto_receipt(jsonb,jsonb,jsonb)'::REGPROCEDURE
  );

  v_original_definition := v_definition;
  v_old := 'v_reference TEXT := trim\(COALESCE\(p_receipt->>''receipt_number'',[[:space:]]*'
    || 'p_disbursement->>''voucher_number'',[[:space:]]*''''\)\);';
  v_new := 'v_reference TEXT := CASE WHEN p_receipt IS NULL AND p_disbursement IS NOT NULL'
    || ' AND p_entry->>''entry_type'' IN (''savings_withdrawal'', ''time_deposit_withdrawal'')'
    || ' THEN ''INTERNAL-'' || replace(gen_random_uuid()::TEXT, ''-'', '''')'
    || ' ELSE trim(COALESCE(p_receipt->>''receipt_number'', p_disbursement->>''voucher_number'', '''')) END;';
  v_definition := regexp_replace(v_definition, v_old, v_new);
  IF v_definition = v_original_definition THEN
    RAISE EXCEPTION 'Unable to patch automatic member withdrawal reference generation';
  END IF;

  v_original_definition := v_definition;
  v_old := 'v_disbursement_id := (v_disbursement_result->>''disbursement_id'')::UUID;';
  v_new := v_old || chr(10)
    || '    v_reference := COALESCE(NULLIF(v_disbursement_result->>''voucher_number'', ''''), v_reference);';
  v_definition := replace(v_definition, v_old, v_new);
  IF v_definition = v_original_definition THEN
    RAISE EXCEPTION 'Unable to patch member withdrawal voucher reference';
  END IF;

  EXECUTE v_definition;
END;
$$;

DO $$
DECLARE
  v_definition TEXT;
  v_original_definition TEXT;
  v_old TEXT;
  v_new TEXT;
BEGIN
  v_definition := pg_get_functiondef('public.record_member_dividend(jsonb)'::REGPROCEDURE);

  v_original_definition := v_definition;
  v_old := 'v_reference TEXT := trim\(COALESCE\(p_distribution->>''reference_number'',[[:space:]]*''''\)\);';
  v_new := 'v_reference TEXT := ''DIV-'' || to_char(clock_timestamp() AT TIME ZONE ''Asia/Manila'', ''YYYYMMDD'')'
    || ' || ''-'' || replace(gen_random_uuid()::TEXT, ''-'', '''');';
  v_definition := regexp_replace(v_definition, v_old, v_new);
  IF v_definition = v_original_definition THEN
    RAISE EXCEPTION 'Unable to patch automatic dividend reference generation';
  END IF;

  EXECUTE v_definition;
END;
$$;

COMMIT;
